import{_ as a,o,c as s,a3 as n}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Links dos documentos na tela de e-mail","description":"","frontmatter":{"title":"Links dos documentos na tela de e-mail","id":"eproc-links-documentos-email","plataforma":"eproc","grupo":"E-mail","plano":"free","desde":"1.12.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-links-documentos-email"}],["meta",{"property":"og:url","content":"https://eploc.com.br/manual/funcionalidades/eproc-links-documentos-email"}],["meta",{"property":"og:title","content":"Links dos documentos na tela de e-mail | Manual do eploc"}],["meta",{"property":"og:description","content":"Manual oficial do eploc, extensão para Chrome e Edge que acelera o trabalho no eproc, SEI e RUPE."}]]},"headers":[],"relativePath":"funcionalidades/eproc-links-documentos-email.md","filePath":"funcionalidades/eproc-links-documentos-email.md"}'),r={name:"funcionalidades/eproc-links-documentos-email.md"};function t(l,e,i,d,c,m){return o(),s("div",null,e[0]||(e[0]=[n('<h1 id="links-dos-documentos-na-tela-de-e-mail" tabindex="-1">Links dos documentos na tela de e-mail <a class="header-anchor" href="#links-dos-documentos-na-tela-de-e-mail" aria-label="Permalink to &quot;Links dos documentos na tela de e-mail&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na lista de documentos para anexar ao e-mail, o nome de cada documento (ex.: <strong>DESPADEC1</strong>) vira um link. Clicar nele abre o documento em nova aba, para você conferir o conteúdo antes de anexá-lo, sem voltar ao processo.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, tela de envio de e-mail do processo, na lista de documentos para anexar.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra o processo normalmente.</li><li>Vá à tela de envio de e-mail.</li><li>Clique no nome de um documento da lista para abri-lo em nova aba. A caixa de seleção da linha não muda.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar. Ao desligar, os nomes voltam a ser texto simples na hora, sem recarregar a página.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><p>Os links são lembrados da tela do processo. Por isso, os documentos ficam sem link quando a tela de e-mail é aberta sem ter passado pelo processo nas últimas horas, ou quando o evento do documento estava numa página de eventos que não foi carregada. Para que todos os documentos ganhem link, carregue todos os eventos na tela do processo antes de ir ao e-mail.</p>',11)]))}const h=a(r,[["render",t]]);export{u as __pageData,h as default};
